// Raw source data for Indian Diplomatic Relations' major (Level 2) countries.
// Merged with major-overrides.ts by scripts/build-data.ts into the final
// per-country JSON consumed by the app.
//
// Content reflects publicly documented, widely reported diplomatic history
// (treaties, wars, summits, trade patterns) to the best of available
// knowledge. Figures are approximate order-of-magnitude values for a recent
// fiscal year unless marked otherwise. Where reliable specifics were not
// available, fields are explicitly marked "Requires verification" rather
// than estimated. The relationship score is an analytical index (see
// /methodology), not an official government rating.

export type EventRow = [year: number, title: string, category: Category, description: string, impact?: string]
export type AgreementRow = [name: string, year: number, category: string, description: string, status?: string]
export type DefenceRow = [name: string, type: string, description: string]
export type MultilateralRow = [org: string, detail: string]
export type NoteRow = [title: string, description: string]
export type SourceRow = [name: string, url: string | null, description: string]
export type LeaderRow = [name: string, position: string, isIndian: boolean]

export type Category =
  | 'Diplomacy' | 'Trade' | 'Defence' | 'Technology'
  | 'Energy' | 'Security' | 'Treaty' | 'Summit' | 'Conflict'

export type Level = 'EXCELLENT' | 'GOOD' | 'AVERAGE' | 'POOR'

export interface CountryRecord {
  id: string
  name: string
  flag: string
  region: string
  capital: string
  level: Level
  overall: number
  sub: { dip: number; eco: number; def: number; tech: number; strat: number; ppl: number }
  summary: string
  complexity?: string
  trade: {
    exports: string; imports: string; total: string
    majorExports: string; majorImports: string; majorSectors: string
  } | null
  events: EventRow[]
  agreements: AgreementRow[]
  defence: DefenceRow[]
  multilateral: MultilateralRow[]
  challenges: NoteRow[]
  cooperation: NoteRow[]
  sources: SourceRow[]
  leaders: LeaderRow[]
}

const NV = 'Latest verified bilateral trade data unavailable — requires verification against Ministry of Commerce & Industry (GoI) records.'
